[CmdletBinding()]param([string]$ProductRoot)
$ErrorActionPreference='Stop';Set-StrictMode -Version 2.0;$root=if($ProductRoot){[IO.Path]::GetFullPath($ProductRoot)}else{[IO.Path]::GetFullPath((Join-Path $PSScriptRoot '..'))}
$routes=@{entity='Test-CustomerWorkspace.ps1';evidence='Test-CustomerWorkspace.ps1';'external-file'='Test-CustomerWorkspace.ps1'};$required=@{entity=@('schema_version','id','customer_id','entity_type','title','lifecycle_status','created_at','relations');evidence=@('evidence_type');'external-file'=@('sha256','size_bytes','media_type','original_name','blob_path')};$rows=@()
foreach($name in $routes.Keys){$path=Join-Path $root "schemas\$name.schema.json";if(-not(Test-Path $path -PathType Leaf)){throw "SCHEMA_PARITY_SCHEMA_MISSING:${name}"};$schema=Get-Content $path -Raw|ConvertFrom-Json;$actual=@();if($schema.PSObject.Properties.Name -contains 'required'){$actual=@($schema.required)}elseif($schema.PSObject.Properties.Name -contains 'allOf'){$actual=@($schema.allOf|% {if($_.PSObject.Properties.Name -contains 'required'){@($_.required)}})};foreach($field in $required[$name]){if($actual -notcontains $field){throw "SCHEMA_PARITY_REQUIRED_FIELD_MISSING:${name}:${field}"}};$route=$routes[$name];if(-not(Test-Path (Join-Path $root "automation\$route") -PathType Leaf)){throw "SCHEMA_PARITY_ROUTE_MISSING:${name}"};$rows+=([ordered]@{type=$name;schema="schemas/$name.schema.json";route="automation/$route";required_fields=$actual})}
$report=[ordered]@{schema_version=1;product_id='spectra';status='PASS';types=$rows;negative_codes=@('ENTITY_CONTRACT_INVALID','EVIDENCE_TYPE_INVALID','EVIDENCE_REFS_REQUIRED','EXTERNAL_FILE_CONTRACT_INVALID','EXTERNAL_BLOB_PATH_HASH_PREFIX_INVALID','EXTERNAL_BLOB_HASH_MISMATCH')};$report|ConvertTo-Json -Depth 10;Write-Host 'PASS: Specialized schema/route parity is complete.'
